#!/usr/bin/env python3
import json, os, sqlite3, threading, webbrowser
from datetime import datetime, date, timedelta
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse
from http.cookies import SimpleCookie

BASE = os.path.dirname(os.path.abspath(__file__))
PHASE = int(open(os.path.join(BASE, 'phase.txt')).read().strip())
DB = os.path.join(BASE, 'personal_assistant.db')
PORT = int(os.environ.get('PORT', '8000'))

def db():
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    return c

def init_db():
    c=db(); x=c.cursor()
    x.executescript('''
    CREATE TABLE IF NOT EXISTS routines(id INTEGER PRIMARY KEY, activity TEXT NOT NULL, day TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS timetable(id INTEGER PRIMARY KEY, subject TEXT NOT NULL, day TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, room TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY, title TEXT NOT NULL, subject TEXT DEFAULT '', deadline TEXT NOT NULL, priority TEXT DEFAULT 'Medium', estimated_minutes INTEGER DEFAULT 30, completed INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS study_sessions(id INTEGER PRIMARY KEY, task_id INTEGER, title TEXT, planned_start TEXT, minutes INTEGER, completed INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS health(id INTEGER PRIMARY KEY, record_date TEXT UNIQUE, workout INTEGER DEFAULT 0, water INTEGER DEFAULT 0, sleep_hours REAL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS weekend(id INTEGER PRIMARY KEY, title TEXT, day TEXT, start_time TEXT, category TEXT);
    ''')
    if x.execute('SELECT COUNT(*) FROM routines').fetchone()[0] == 0:
        rows=[('Wake up','Weekday','05:00','05:10'),('Workout','Weekday','05:30','06:30'),('Get ready','Weekday','06:30','07:25'),('Travel to college','Weekday','07:25','08:40'),('College classes','Weekday','09:15','16:55'),('Travel home','Weekday','17:20','18:15'),('Freshen up and rest','Weekday','18:15','19:00'),('Dinner','Weekday','19:00','19:30'),('Study and recreation','Weekday','19:30','22:40'),('Prepare for tomorrow','Weekday','22:40','23:00'),('Sleep','Weekday','23:00','05:00')]
        x.executemany('INSERT INTO routines(activity,day,start_time,end_time) VALUES(?,?,?,?)',rows)
    c.commit(); c.close()

def rows(table):
    c=db(); r=[dict(x) for x in c.execute(f'SELECT * FROM {table} ORDER BY id DESC')]; c.close(); return r

def now_context():
    n=datetime.now(); current=n.strftime('%H:%M'); weekday=n.strftime('%A')
    c=db(); items=[dict(r) for r in c.execute("SELECT * FROM routines WHERE day=? OR day='Daily' OR (day='Weekday' AND ? NOT IN ('Saturday','Sunday')) OR (day='Weekend' AND ? IN ('Saturday','Sunday')) ORDER BY start_time",(weekday,weekday,weekday))]
    classes=[dict(r) for r in c.execute("SELECT * FROM timetable WHERE day=? ORDER BY start_time",(weekday,))]
    c.close(); all_items=items+[{**x,'activity':x['subject']+' class'} for x in classes]
    all_items.sort(key=lambda x:x['start_time'])
    current_item=next((x for x in all_items if x['start_time'] <= current < x['end_time']),None)
    next_item=next((x for x in all_items if x['start_time'] > current),None)
    return n,current,current_item,next_item

def recommendation():
    n,cur,current_item,next_item=now_context(); c=db()
    tasks=[dict(r) for r in c.execute("SELECT * FROM tasks WHERE completed=0 ORDER BY deadline, CASE priority WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END")]; c.close()
    cur_name=current_item['activity'] if current_item else 'Free time'
    nxt=f"{next_item['activity']} at {next_item['start_time']}" if next_item else 'No more scheduled activities'
    action='Review your dashboard and prepare for the next activity.'
    if tasks:
        t=tasks[0]; action=f"Work on '{t['title']}' ({t['subject'] or 'General'}). It is your highest-priority pending task."
    if current_item and ('Travel' in cur_name or 'bus' in cur_name.lower()): action='Use travel time for flashcards, reading notes, or educational audio.'
    if current_item and ('class' in cur_name.lower()): action='Focus on the current class and note any new assignment immediately.'
    warning=''
    h=rows('health')
    if h and float(h[0].get('sleep_hours') or 0) < 7: warning='Sleep was below 7 hours. Plan an earlier bedtime tonight.'
    return {'current':cur_name,'next':nxt,'action':action,'reminder':warning or ('Upcoming: '+nxt)}

def make_plan():
    c=db(); tasks=[dict(r) for r in c.execute("SELECT * FROM tasks WHERE completed=0 ORDER BY deadline, CASE priority WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END LIMIT 3")]
    c.execute('DELETE FROM study_sessions')
    starts=['19:30','20:25','21:20']; plans=[]
    for i,t in enumerate(tasks):
        mins=min(max(int(t['estimated_minutes'] or 30),25),45)
        c.execute('INSERT INTO study_sessions(task_id,title,planned_start,minutes) VALUES(?,?,?,?)',(t['id'],t['title'],starts[i],mins))
        plans.append({'title':t['title'],'start':starts[i],'minutes':mins})
    c.commit(); c.close(); return plans

def chat_reply(message):
    m=message.lower().strip(); rec=recommendation()
    if 'what should' in m or 'do now' in m: return f"Current: {rec['current']}. Next: {rec['next']}. Recommendation: {rec['action']}"
    if 'next class' in m:
        _,cur,_,_=now_context(); wd=datetime.now().strftime('%A'); c=db(); r=c.execute('SELECT * FROM timetable WHERE day=? AND start_time>? ORDER BY start_time LIMIT 1',(wd,cur)).fetchone(); c.close()
        return f"Your next class is {r['subject']} at {r['start_time']} in {r['room'] or 'the assigned room'}." if r else 'No more classes are scheduled today.'
    if 'pending' in m or 'assignment' in m:
        ts=[x for x in rows('tasks') if not x['completed']]
        return 'Pending: '+', '.join(f"{x['title']} (due {x['deadline']})" for x in ts[:5]) if ts else 'You have no pending assignments.'
    if 'plan' in m or 'study' in m:
        p=make_plan(); return 'Study plan: '+ '; '.join(f"{x['start']} — {x['title']} for {x['minutes']} min" for x in p) if p else 'Add a pending task first, then I can create a study plan.'
    if 'sleep' in m:
        hs=rows('health'); return f"Your latest recorded sleep is {hs[0]['sleep_hours']} hours. Aim for at least 7 hours." if hs else 'No sleep record found. Add today’s health details.'
    return "Try: 'What should I do now?', 'What is my next class?', 'Show pending assignments', or 'Plan my study time'."

